import axios from 'axios';
import {useEffect, useState } from "react";
function Student() {
  const [id, setId] = useState('');
  const [name, setName] = useState('');
  const [last_name, setLastName] = useState('');
  const [father_name, setFatherName] = useState('');
  const [course, setCourse] = useState('');
  const [address, setAddress] = useState('');
  const [fee, setFee] = useState('');
  const [students, setUsers] = useState([]);
  useEffect(() =>{
    (async()=>await Load())();
  }, []);

  async function Load(){
    const result = await axios.get(
      "http://127.0.0.1:8000/student/");
      setUsers(result.data);
      console.log(result.data);
  }

  async function save(event){
    event.preventDefault();
    try{
      await axios.post("http://127.0.0.1:8000/student/",{
        id: id,
        name: name,
        last_name: last_name,
        father_name: father_name,
        course: course,
        address: address,
        fee: fee
      });
      alert("Student Registration Successful");
      setId("");
      setName("");
      setLastName("");
      setFatherName("");
      setCourse("");
      setAddress("");
      setFee("");
      Load();
    }
    catch(err){
      alert("Student Registration Failed");
    }
  }

  async function editStudent(students){
    setName(students.name);
    setLastName(students.last_name);
    setFatherName(students.father_name);
    setCourse(students.course);
    setAddress(students.address);
    setFee(students.fee);
    setId(students.id);
  }

  async function DeleteStudent(id){
    await axios.delete("http://127.0.0.1:8000/student/"+id);
    alert("Student Deleted Successfully");
    console.log("Data Deleted Failed");
    Load();
  }

  async function update(event){
    event.preventDefault();
    try{
      await axios.put("http://127.0.0.1:8000/student/" + students.find(u => u.id === id).id || id,{
        id: id,
        name: name,
        last_name: last_name,
        father_name: father_name,
        course: course,
        address: address,
        fee: fee
      });
      alert("Record Updated Successfully");
      setId("");
      setName("");
      setLastName("");
      setFatherName("");
      setCourse("");
      setAddress("");
      setFee("");
      Load();
    }
    catch(err){
      alert("User Registration Failed");
    }
  }

  if(students.length <= 0) return null;

